{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 작은 가게(업소)의 금연실천 표지 설치 지원 근거 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 금연환경 조성 및 간접흡연 피해방지조례 제9조제5항에 따르면, 시장은 간접흡연 피해를 예방하기 위하여 금연실천을 권장하는 업소 또는 공동주택에 대해 일정한 표지 등의 설치를 지원할 수 있다. 따라서 작은 가게를 운영하는 업소라도 금연실천을 권장하는 업소에 해당하면 표지 설치 지원의 근거가 있다. 다만 지원은 시장의 재량(할 수 있다)이며, 구체적인 지원 대상·표지의 종류·범위 등은 조례에서 직접 정하지 않는다.",
          "b_ids": "금연:제9조제5항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
